        // We observe acceptance via checking that depositAmt >= 1 ether (assumed) and that the Deposit call did not revert.
        // The mutant will reject depositAmt == 1 ether (it returns) causing balances to differ for some fuzz inputs.

        uint bal = c.balances(depositor);

        uint expectedAfter = 0;
        // If deposit was accepted (depositAmt >= 1 ether and Deposit didn't revert)
        // Deposit in reference only returns (no revert) and increases balances by depositAmt.
        // Our call used raw .call; ensure it didn't revert
        if (okDeposit) {
            // expected before cashout is depositAmt
            expectedAfter = depositAmt;
            if (okCashOut) expectedAfter -= cashOutAmt;
        } else {
            // If deposit reverted (shouldn't for reference with depositAmt>=1 ether), we cannot assert expected numeric relation
            // So make a weak expected value equal to current balance to make assertion tautological in that rare case
            expectedAfter = bal;
        }

        // The single assertion reading c: reference C satisfies this for all admissible inputs; mutant fails for some
        assertTrue(bal == expectedAfter);
    }
}

