        vm.assume(depositor != address(0));
        // bound depositAmount and cashoutAmount to reasonable ranges to avoid overflows in test env
        depositAmount = bound(depositAmount, 0, 10 ether);
        cashoutAmount = bound(cashoutAmount, 0, 10 ether);

        // Ensure depositor has ETH to send
        vm.deal(depositor, depositAmount + 1 ether);

        // Make depositor perform Deposit with fuzzed amount
        vm.prank(depositor);
        // call payable Deposit
        (bool okDeposit,) = address(c).call{value: depositAmount}(abi.encodeWithSignature("Deposit()"));
        // After deposit, attempt a CashOut by depositor of fuzzed amount
        vm.prank(depositor);
        // Use try/catch to call CashOut and record success (but we only assert on balances mapping)
        try c.CashOut(cashoutAmount) {
            // no-op
        } catch {
            // ignore revert
        }

        // General invariant to check: for the reference contract, if depositAmount >= c.MinDeposit() then
        // balances(depositor) equals (sum of successful deposits - successful cashouts). In our scenario
        // we only did at most one deposit and one cashout from depositor, so balances(depositor) must be <= depositAmount
        // and if depositAmount < c.MinDeposit() then balances should be 0. The mutant that returns early on msg.value==MinDeposit
        // will leave balances at 0 for depositAmount == MinDeposit, breaking the rule for some fuzzed inputs.

        // Read the mapping via the public getter
        uint256 finalBal = c.balances(depositor);

        // Single assertion: if depositAmount < MinDeposit then balance is 0; else balance <= depositAmount
        // This is a general property the reference satisfies for all inputs, while the mutant can violate the
        // expected non-zero behavior for depositAmount == MinDeposit (leaving balance 0 when it should be MinDeposit - cashout)
        uint256 minDep = c.MinDeposit();
        if (depositAmount < minDep) {
            assertTrue(finalBal == 0);
        } else {
            assertTrue(finalBal <= depositAmount);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single test function: drive Deposit once with value `val` and assert balance increased accordingly
    // params: val - amount to send to Deposit, preBalance - previous observed balance (caller)
    function runTest(uint val) public payable {
        // require we have enough funds in this contract to forward
        require(address(this).balance >= val, "insufficient test balance");

        // observe previous recorded balance for this contract's address
        uint before = c.balances(address(this));

        // require val is strictly greater than MinDeposit so original contract will accept it
        require(val > c.MinDeposit(), "val must be > MinDeposit");

        // perform the deposit call forwarding Ether
        c.Deposit{value: val}();

        // read new balance
        uint after = c.balances(address(this));

        // General rule: when depositing more than MinDeposit, recorded balance increases by exactly val
        assert(after == before + val);
    }

    // allow funding this test contract so it can forward Ether
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        // we need some Ether to send
        require(address(this).balance >= amount);
        // Call Deposit with amount; original accepts only if amount > MinDeposit, mutant accepts only if amount <= MinDeposit
        uint before = address(c).balance;
        c.Deposit{value: amount}();
        uint afterBal = address(c).balance;
        // General rule: if amount is strictly greater than MinDeposit (as observed via change), the contract should have increased its balance by exactly amount
        // We cannot read MinDeposit directly (it's public though), so call its getter
        uint minDep = c.MinDeposit();
        assert((amount > minDep) ? (afterBal == before + amount) : true);
    }
    receive() external payable {}
}
